select * from customer;

--1. Revenue Analysis
--Compared total revenue generated by male and female customer.
SELECT 
    gender,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY gender;
-- Answer:
-- Female customers generated a total revenue of 75,191.
-- Male customers generated a total revenue of 157,890.
-- Male customers contribute more revenue than female customers.


--2.Discount & Spending Analysis
--Indentified discount users whose purchase amounts were at or above the average
SELECT customer_id, purchase_amount 
       FROM customer
       WHERE discount_applied = 'Yes'
       AND purchase_amount >= (
       SELECT AVG(purchase_amount)
       FROM customer);

select * from customer;

--3.Product Rating Analysis
--Ranked the top 5 product by average review rating
SELECT
    item_purchased,
    ROUND(AVG(review_rating)::numeric, 2) AS average_rating
FROM customer
GROUP BY item_purchased
ORDER BY average_rating DESC
LIMIT 5;
-- Answer:
-- Identified the top 5 products based on average customer review ratings.
-- Gloves received the highest average rating of 3.86.
-- This analysis helps businesses identify highly rated products
-- and understand customer satisfaction.


-- 4. Shipping Analysis
-- Compared average purchase amount for Standard and Express shipping.
SELECT
    shipping_type,
    ROUND(AVG(purchase_amount), 2) AS average_purchase
FROM customer
WHERE shipping_type IN ('Standard', 'Express')
GROUP BY shipping_type;
-- Answer:
-- Express Shipping customers have a higher average purchase amount (60.48).
-- Standard Shipping customers have an average purchase amount of 58.46.
-- Express Shipping exceeds Standard Shipping by 2.02.

select * from customer;

-- 5. Subscription Analysis
-- Compared customer counts, average spending,
-- and total revenue between subscribers and non-subscribers.
SELECT
    subscription_status,
    COUNT(customer_id) AS total_customer,
    ROUND(AVG(purchase_amount)::numeric, 2) AS avg_spend,
    ROUND(SUM(purchase_amount)::numeric, 2) AS total_revenue
FROM customer
GROUP BY subscription_status
ORDER BY total_revenue DESC, avg_spend DESC;
-- Answer:
-- Non-subscribers generated the highest total revenue of 170,436.
-- Subscribers generated total revenue of 62,645.
-- Non-subscribers had a slightly higher average spending of 59.87
-- compared to subscribers at 59.49.


-- 6. Discount Dependency Analysis
-- Identify the top 5 products by percentage of purchases with discounts applied.
SELECT item_purchased,
    ROUND(
        100.0 * SUM(
            CASE WHEN discount_applied = 'Yes' THEN 1
                ELSE 0 END) / COUNT(*), 2) AS discount_rate
FROM customer
GROUP BY item_purchased
ORDER BY discount_rate DESC
LIMIT 5;
-- Answer:
-- Hat has the highest discount dependency at 50%,
-- followed by Sneakers (49.66%), Coat (49.07%),
-- Sweater (48.17%), and Pants (47.37%).
-- All top 5 products have discount rates above 47%,
-- indicating that discounts play an important role
-- in influencing customer purchasing decisions.

select * from customer;

-- 7. Customer Segmentation
-- Classified customers into New, Returning, and Loyal segments
-- based on previous purchases.
SELECT
    CASE
        WHEN previous_purchases = 1 THEN 'New'
        WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
        ELSE 'Loyal'
    END AS customer_segment,
    COUNT(*) AS total_customers
FROM customer
GROUP BY customer_segment
ORDER BY total_customers DESC;
--Answer:
-- Loyal customers represent the largest segment with 3,116 customers.
-- Returning customers account for 701 customers.
-- New customers represent the smallest segment with only 83 customers.


-- 8. Product Popularity Analysis
-- Identified the top 3 most purchased products within each category.

WITH item_count AS (
    SELECT
        category,
        item_purchased,
        COUNT(customer_id) AS total_orders,
        ROW_NUMBER() OVER (
            PARTITION BY category
            ORDER BY COUNT(customer_id) DESC
        ) AS product_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT category,item_purchased,total_orders,product_rank
FROM item_count
WHERE product_rank <= 3;

--9. Repeat Buyer Analysis
--Compared subscription status among customers with more than 5 previous purchases.
select subscription_status,
count(customer_id) as repeated_buyers
from customer
where previous_purchases>5
group by subscription_status;
-- Answer:
-- 2,518 repeat buyers are not subscribed, while 958 have an active subscription.
-- This indicates that a large number of frequent customers have not adopted subscriptions.

--10.Age Group Revenue Analysis 
--Compared total revenue across customer age groups.
select age_group, sum(purchase_amount) as total_revenue
from customer
group by age_group
order by total_revenue desc;
-- Answer:
-- Young adults generate the highest revenue at 62,142.
-- Middle-aged customers contribute 59,197 in revenue.
-- Adults generate 55,978, while seniors contribute the lowest revenue at 55,763.








